17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        if (owner.getRegistrationDate() == null) {
109	            owner.setRegistrationDate(LocalDate.now());
110	        }
111	        if (isDuplicateTelephone(owner)) {
112	            throw new DuplicateOwnerException("An owner with telephone "
113	                + owner.getTelephone() + " already exists");
114	        }
115	        if (isDuplicateEmail(owner)) {
116	            throw new DuplicateOwnerException("An owner with email "
117	                + owner.getEmail() + " already exists");
118	        }
119	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    /**
128	     * Determines whether any other owner already uses the candidate's telephone number.
129	     * The comparison ignores letter case and surrounding or repeated whitespace.
130	     *
131	     * @param candidate the owner about to be created
132	     * @return {@code true} if an owner with the same telephone is already present in the data store
133	     */
134	    private boolean isDuplicateTelephone(Owner candidate) {
135	        String telephone = normalize(candidate.getTelephone());
136	        return this.clinicService.findAllOwners().stream()
137	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
138	    }
139	
140	    /**
141	     * Determines whether any other owner already uses the candidate's email address.
142	     * An absent or blank email is never considered a duplicate. The comparison ignores
143	     * letter case and surrounding or repeated whitespace.
144	     *
145	     * @param candidate the owner about to be created
146	     * @return {@code true} if an owner with the same email is already present in the data store
147	     */
148	    private boolean isDuplicateEmail(Owner candidate) {
149	        String email = normalize(candidate.getEmail());
150	        if (email == null || email.isBlank()) {
151	            return false;
152	        }
153	        return this.clinicService.findAllOwners().stream()
154	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
155	    }
156	
157	    /**
158	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
159	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
160	     * any run of internal whitespace is collapsed to a single space, and the result is
161	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
162	     * normalise to {@code "john smith"}.
163	     *
164	     * @param value the raw value, possibly {@code null}
165	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
166	     */
167	    private static String normalize(String value) {
168	        if (value == null) {
169	            return null;
170	        }
171	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        currentOwner.setAddress(ownerFieldsDto.getAddress());
182	        currentOwner.setCity(ownerFieldsDto.getCity());
183	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
